#!/usr/bin/env bash\nset -e\n# Load environment variables if .env exists\nif [ -f "$(dirname "$0")/../config/.env" ]; then\n  export $(grep -v '^#' "$(dirname "$0")/../config/.env" | xargs)\nfi\nBACKUP_DIR="${BACKUP_DIR:-./backups}"\nLATEST_BACKUP=$(ls -t "$BACKUP_DIR"/backup_*.sql 2>/dev/null | head -n1)\nif [ -z "$LATEST_BACKUP" ]; then\n  echo "No backup files found."\n  exit 1\nfi\nTEMP_DB="temp_restore_db"\necho "Restoring $LATEST_BACKUP into temporary database $TEMP_DB ..."\npsql "$POSTGRES_URI" -c "DROP DATABASE IF EXISTS $TEMP_DB;"\npsql "$POSTGRES_URI" -c "CREATE DATABASE $TEMP_DB;"\n# Restore the dump into the temporary database\npg_restore -d "$(echo $POSTGRES_URI | sed -e 's|^postgresql://||' -e 's|/[^/]*$||')/$TEMP_DB" "$LATEST_BACKUP"\n# Simple health‑check query\npsql "$(echo $POSTGRES_URI | sed -e 's|^postgresql://||' -e 's|/[^/]*$||')/$TEMP_DB" -c "SELECT 1;"\necho "Restore verification completed successfully."\n# Reminder: make this script executable\n# chmod +x $(basename "$0")\n